package io.github.jamiecrock.matching;

import java.util.List;

/**
 * Outcome of submitting, cancelling or amending an order.
 *
 * @param orderId      id assigned by the book (or the id that was targeted)
 * @param status       resulting order status
 * @param filled       quantity filled by this call
 * @param remaining    quantity still resting on the book afterwards
 * @param trades       executions generated by this call, in order
 * @param rejectReason human-readable reason when {@code status == REJECTED}, otherwise {@code null}
 */
public record ExecutionReport(
        long orderId, OrderStatus status, long filled, long remaining, List<Trade> trades, String rejectReason) {

    public ExecutionReport {
        trades = List.copyOf(trades);
    }

    static ExecutionReport rejected(long orderId, String reason) {
        return new ExecutionReport(orderId, OrderStatus.REJECTED, 0, 0, List.of(), reason);
    }

    /** Volume-weighted average fill price in ticks, or 0 if nothing traded. */
    public double averagePrice() {
        long qty = 0;
        double notional = 0;
        for (Trade t : trades) {
            qty += t.quantity();
            notional += (double) t.price() * t.quantity();
        }
        return qty == 0 ? 0 : notional / qty;
    }
}
